\begin{ex}%[8H9V4]
\immini[thm]{
Quan sát hình bên.

 Chứng minh ${ \triangle ACD\backsim \triangle KCA}$;

  Chứng minh $AC^{2}=CK\cdot CD$;

 Biết ${CD=85}$ cm, ${CK=\dfrac{320}{17}}$ cm. Tính ${AD}$.
}{
\begin{tikzpicture}[scale=1, font=\footnotesize,>=stealth]
            %Gán số liệu.
            \def\canhAB{3};\def\canhCA{4};
            %Gán tọa độ.
            \coordinate (A) at (0,0);
            \coordinate (B) at (90:\canhAB);
