            \draw (A)--(B)--(C)--cycle (A)--(H);
            \draw pic[draw, angle radius=3mm, angle eccentricity=1.5]{right angle = B--A--C}
            pic[draw, angle radius=3mm, angle eccentricity=1.5]{right angle = B--H--A}
            ;

    \filldraw[black] (A) circle (1pt) node[below left] {$A$};
    \filldraw[black] (B) circle (1pt) node[above left] {$C$};
    \filldraw[black] (C) circle (1pt) node[below right] {$D$};
   \filldraw[black] (H) circle (1pt) node[above right]{$K$};
